// Compare the Drive listing against the ingest ledger.
// Only files that are new, or whose Drive version moved, get re-embedded.
const ledger = new Map();
for (const row of $input.all()) {
  const j = row.json;
  if (j && j.doc_id) {
    ledger.set(String(j.doc_id), String(j.doc_version == null ? '' : j.doc_version));
  }
}

const queued = [];
for (const f of $('List KB Files').all()) {
  const j = f.json;
  if (!j || !j.id) continue;

  const docId = String(j.id);
  const version = String(j.version == null ? '' : j.version);
  const known = ledger.get(docId);

  // Unchanged since the last ingest. Skip it and save the embedding spend.
  if (known !== undefined && known === version) continue;

  queued.push({
    json: {
      doc_id: docId,
      doc_title: String(j.name || 'Untitled'),
      doc_version: version,
      doc_url: String(j.webViewLink || ''),
      mime_type: String(j.mimeType || ''),
      change_type: known === undefined ? 'new' : 'changed',
    },
  });
}

return queued;

// Both triggers land here. Flatten them into one ticket shape so nothing
// downstream has to care which door the ticket came through.
const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  const payload = j.body && typeof j.body === 'object' ? j.body : j;
  const isGmail = Boolean(j.threadId || j.labelIds);

  const rawFrom = String(isGmail
    ? (j.from || '')
    : (payload.from_email || payload.email || payload.from || ''));
  const fromEmail = rawFrom.indexOf('<') !== -1
    ? rawFrom.replace(/.*<(.+)>.*/, '$1').trim()
    : rawFrom.trim();

  const body = isGmail
    ? (j.text || j.snippet || '')
    : (payload.body || payload.message || payload.description || '');

  out.push({
    json: {
      ticket_ref: String(isGmail
        ? j.id
        : (payload.ticket_id || payload.id || 'hd-' + Date.now())),
      channel: isGmail ? 'gmail' : 'helpdesk',
      thread_id: String(isGmail ? (j.threadId || '') : ''),
      message_id: String(isGmail ? (j.id || '') : ''),
      from_email: fromEmail,
      subject: String((isGmail ? j.subject : payload.subject) || '(no subject)'),
      // Hard cap. A pasted log file should not become a five-figure token bill.
      body_raw: String(body).slice(0, 8000),
      received_at: new Date().toISOString(),
    },
  });
}

return out;

// Replace direct identifiers with tokens BEFORE any model sees the ticket.
// The map travels with the item and is applied in reverse in "Unmask Answer",
// so the customer still reads a normal reply.
//
// Order matters: IBAN and card patterns are greedy, so they run before phone.
const RULES = [
  { name: 'EMAIL', re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}/g },
  { name: 'IBAN',  re: /[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}/g },
  { name: 'CARD',  re: /[0-9](?:[ -]?[0-9]){12,18}/g },
  { name: 'PHONE', re: /[+]?[0-9][0-9 ()-]{7,}[0-9]/g },
];

const out = [];

for (const item of $input.all()) {
  const j = item.json || {};
  let text = String(j.body_raw || '');
  const map = {};
  let seq = 0;

  for (const rule of RULES) {
    text = text.replace(rule.re, function (match) {
      seq += 1;
      const token = '[[' + rule.name + '_' + seq + ']]';
      map[token] = match;
      return token;
    });
  }

  out.push({
    json: Object.assign({}, j, {
      body_masked: text,
      pii_map: map,
      pii_count: Object.keys(map).length,
    }),
  });
}

return out;

