// The chain emits only its parsed output, so re-join it with the ticket
// fields. Everything downstream then reads one flat record instead of
// reaching back through three nodes.
const c = $json.output || {};
const t = $('Mask PII').item.json;

return {
  json: {
    ticket_ref: t.ticket_ref,
    channel: t.channel,
    thread_id: t.thread_id,
    message_id: t.message_id,
    from_email: t.from_email,
    subject: t.subject,
    body_masked: t.body_masked,
    pii_map: t.pii_map,
    pii_count: t.pii_count,
    received_at: t.received_at,
    category: c.category || 'other',
    intent: c.intent || '',
    urgency: c.urgency || 'normal',
    sentiment: c.sentiment || 'neutral',
    language: c.language || 'en',
    is_answerable_from_docs: Boolean(c.is_answerable_from_docs),
    // Fail closed: if the classifier gave us nothing usable, a human gets it.
    policy_class: c.policy_class || 'restricted',
  },
};

