// Collapse ticket, draft and verdict into the one record the gate reads.
const critic = $json.output || {};
const draft = $('Draft Grounded Answer').item.json.output || {};
const ticket = $('Assemble Ticket Record').item.json;

const citations = Array.isArray(draft.citations) ? draft.citations : [];
const unsupported = Array.isArray(draft.unsupported_claims) ? draft.unsupported_claims : [];
const issues = Array.isArray(critic.issues) ? critic.issues : [];

function num(v) {
  return typeof v === 'number' && isFinite(v) ? v : 0;
}

return {
  json: Object.assign({}, ticket, {
    draft_markdown: String(draft.answer_markdown || ''),
    citations: citations,
    citation_count: citations.length,
    draft_confidence: num(draft.confidence),
    unsupported_claims: unsupported,
    unsupported_count: unsupported.length,
    kb_gap_note: String(draft.kb_gap_note || ''),
    critic_accuracy: num(critic.accuracy),
    critic_groundedness: num(critic.groundedness),
    critic_tone: num(critic.tone),
    critic_completeness: num(critic.completeness),
    critic_overall: num(critic.overall),
    // Fail closed if the critic returned nothing parseable.
    critic_verdict: String(critic.verdict || 'escalate'),
    critic_issues: issues,
  }),
};

// Two branches arrive here: the auto-send path, which still carries the
// merged record, and the approval path, whose item is the approval result.
// Recover the record either way, then put the real identifiers back.
let record = $json;
if (!record || !record.draft_markdown) {
  record = $('Merge Draft And Verdict').item.json;
}

// Did a human sign this off, or did it clear the gate on its own?
let approvedByHuman = false;
try {
  const approval = $('Request Human Approval').item.json;
  approvedByHuman = Boolean(approval && approval.data && approval.data.approved);
} catch (err) {
  approvedByHuman = false;
}

let text = String(record.draft_markdown || '');
const map = record.pii_map || {};
for (const token of Object.keys(map)) {
  text = text.split(token).join(map[token]);
}

const sources = (record.citations || [])
  .map(function (c) { return '- ' + c.title + ': ' + c.source; })
  .join('<br>');

const html = text.split(String.fromCharCode(10)).join('<br>')
  + (sources ? '<br><br><b>Sources</b><br>' + sources : '');

return {
  json: Object.assign({}, record, {
    final_answer: text,
    final_answer_html: html,
    approved_by_human: approvedByHuman,
    outcome: approvedByHuman ? 'approved_sent' : 'auto_sent',
  }),
};

// Three very different branches land here. A restricted ticket never went
// near the drafting agent, so there is no draft to attach. A declined ticket
// has a full draft and a list of objections. An agent error has neither.
// Handle all of them without throwing.
let record = $('Assemble Ticket Record').item.json;
let reason = 'restricted_category';
let draft = '';
let issues = [];
let criticOverall = null;

try {
  const merged = $('Merge Draft And Verdict').item.json;
  if (merged && merged.draft_markdown) {
    record = merged;
    draft = String(merged.draft_markdown || '');
    issues = Array.isArray(merged.critic_issues) ? merged.critic_issues : [];
    criticOverall = merged.critic_overall;
    reason = 'declined_by_reviewer';
  }
} catch (err) {
  // Restricted or errored path: Merge Draft And Verdict never ran for this item.
}

// Restore the identifiers for the human, who is allowed to see them.
const map = record.pii_map || {};
let body = String(record.body_masked || '');
for (const token of Object.keys(map)) {
  body = body.split(token).join(map[token]);
}

return {
  json: Object.assign({}, record, {
    escalation_reason: reason,
    escalation_body: body,
    escalation_draft: draft,
    escalation_issues: issues,
    escalation_critic_overall: criticOverall,
    outcome: 'escalated',
  }),
};

// HTML only, so there is no newline escaping to get wrong.
const m = $json;
const gaps = Array.isArray(m.kb_gaps) ? m.kb_gaps : [];
const cats = Array.isArray(m.escalation_categories) ? m.escalation_categories : [];

function row(label, value) {
  return '<tr><td style="padding:4px 16px 4px 0">' + label
    + '</td><td><b>' + value + '</b></td></tr>';
}

const gapRows = gaps.length
  ? gaps.map(function (g) {
      return '<li>' + g.category + ' (' + g.hits + 'x): ' + g.kb_gap_note + '</li>';
    }).join('')
  : '<li>No gaps reported. Either coverage is good, or volume was low.</li>';

const catRows = cats.length
  ? cats.map(function (c) {
      return '<li>' + c.category + ': ' + c.hits + '</li>';
    }).join('')
  : '<li>Nothing escalated this week.</li>';

const html =
  '<h2>Support replies, last 7 days</h2>' +
  '<table>' +
  row('Tickets handled', m.tickets) +
  row('Answered automatically', m.auto_answered automatically) +
  row('Sent after human approval', m.human_approved) +
  row('Escalated', m.escalated) +
  row('Suppressed as noise', m.suppressed) +
  row('Auto-answer rate', m.auto_answer_rate_pct == null ? 'n/a' : m.auto_answer_rate_pct + '%') +
  row('Average critic score', m.avg_critic_score == null ? 'n/a' : m.avg_critic_score + '/10') +
  '</table>' +
  '<h3>Documents that should exist but do not</h3><ul>' + gapRows + '</ul>' +
  '<h3>Where escalations came from</h3><ul>' + catRows + '</ul>' +
  '<p style="color:#666">Auto-answer rate excludes suppressed noise, so it reflects real tickets only.</p>';

return { json: Object.assign({}, m, { digest_html: html }) };
